(function(E){ const x = E["exam-01"] = E["exam-01"] || {units:{}}; (x.units = x.units || {})["x01-l4"] = {"id":"x01-l4","patterns":["L4-nature","PARA-signpost"],"title":{"en":"Listening Part 4: a lecture","tr":"Listening Part 4: bir ders anlatımı","fa":"Listening Part 4: یک سخنرانی"},"objective":{"en":"In this lesson you will learn to follow a lecture by its signposts and complete ten notes with the exact word the speaker says.","tr":"Bu derste bir dersi geçiş ifadeleriyle takip etmeyi ve on notu konuşanın söylediği kelimenin tam aynısıyla tamamlamayı öğreneceksin.","fa":"در این درس یاد می‌گیری یک سخنرانی را با نشانه‌های گفتاری‌اش دنبال کنی و ده یادداشت را دقیقاً با همان کلمه‌ای که گوینده می‌گوید کامل کنی."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Listening Part 4: a lecture","tr":"Listening Part 4: bir ders anlatımı","fa":"Listening Part 4: یک سخنرانی"},"objective":{"en":"In this lesson you will learn to follow a lecture by its signposts and complete ten notes with the exact word the speaker says.","tr":"Bu derste bir dersi geçiş ifadeleriyle takip etmeyi ve on notu konuşanın söylediği kelimenin tam aynısıyla tamamlamayı öğreneceksin.","fa":"در این درس یاد می‌گیری یک سخنرانی را با نشانه‌های گفتاری‌اش دنبال کنی و ده یادداشت را دقیقاً با همان کلمه‌ای که گوینده می‌گوید کامل کنی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"10"},{"label":{"en":"Speakers","tr":"Konuşan","fa":"گوینده"},"value":"1"},{"label":{"en":"Word limit","tr":"Kelime sınırı","fa":"سقف کلمه"},"value":{"en":"1 word","tr":"1 kelime","fa":"۱ کلمه"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: natural rubber","tr":"Bu sınav: doğal kauçuk","fa":"این آزمون: لاستیک طبیعی"},"intro":{"en":"Part 4 is one academic talk. Nature topics (animals, plants, natural materials) are the largest group, followed by history and society. The talk moves through the note headings in order.","tr":"Part 4 tek bir akademik konuşmadır. Doğa konuları (hayvanlar, bitkiler, doğal malzemeler) en büyük gruptur, ardından tarih ve toplum gelir. Konuşma not başlıklarını sırayla izler.","fa":"Part 4 یک سخنرانی دانشگاهی است. موضوع‌های طبیعت (جانوران، گیاهان، مواد طبیعی) بزرگ‌ترین گروه‌اند و بعد تاریخ و جامعه. سخنرانی عنوان‌های یادداشت را به ترتیب جلو می‌برد."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x01-l4-ctx","exam":true,"patterns":["L4-nature","PARA-signpost"],"often":{"pattern":"L4-nature","n":14,"of":40,"label":{"en":"Comes up often in the real exam: 14 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 14’ünde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۴ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"A lecture on a plant product","tr":"Bir bitki ürünü hakkında bir ders","fa":"درسی درباره‌ی یک محصول گیاهی"},"asks":{"en":"One lecturer explains a natural material: where it comes from, how it is collected, who produces it, what threatens the supply and what could replace it. The notes follow the same headings in the same order.","tr":"Bir öğretim görevlisi doğal bir malzemeyi anlatıyor: nereden geldiğini, nasıl toplandığını, kimin ürettiğini, arzı neyin tehdit ettiğini ve yerine ne geçebileceğini. Notlar aynı başlıkları aynı sırayla izler.","fa":"یک استاد یک ماده‌ی طبیعی را توضیح می‌دهد: از کجا می‌آید، چطور جمع می‌شود، چه کسی تولیدش می‌کند، چه چیزی تأمینش را تهدید می‌کند و چه چیزی می‌تواند جایش را بگیرد. یادداشت‌ها همان عنوان‌ها را به همان ترتیب دنبال می‌کنند."},"fields":["Origin","How it is collected","Where and by whom it is produced","Main use","Problems","The alternative"],"words":[{"a":"originally grew","b":"is native to / first came from","tr":"aslen yetiştiği yer","fa":"در اصل می‌رویید"},{"a":"collected","b":"harvested / gathered","tr":"toplanır","fa":"جمع می‌شود"},{"a":"produced by","b":"most of it comes from","tr":"... tarafından üretilir","fa":"تولید می‌شود توسط"},{"a":"mainly used for","b":"the biggest use is / most of it goes into","tr":"çoğunlukla ... için kullanılır","fa":"بیشتر برای ... استفاده می‌شود"},{"a":"genetically similar","b":"little variety / almost identical","tr":"genetik olarak benzer","fa":"از نظر ژنتیکی شبیه"},{"a":"disease","b":"an infection / a virus or a fungus","tr":"hastalık","fa":"بیماری"},{"a":"low prices","b":"it doesn’t pay / it earns very little","tr":"düşük fiyatlar","fa":"قیمت‌های پایین"},{"a":"synthetic","b":"man-made / artificial","tr":"sentetik","fa":"مصنوعی"},{"a":"cannot stand heat","b":"doesn’t cope with high temperatures","tr":"ısıya dayanamaz","fa":"گرما را تحمل نمی‌کند"},{"a":"needs little water","b":"grows in dry regions","tr":"az su ister","fa":"آب کمی لازم دارد"},{"a":"allergy","b":"a bad reaction to","tr":"alerji","fa":"آلرژی"},{"a":"harvested","b":"the whole plant is cut and collected","tr":"hasat edilir","fa":"برداشت می‌شود"}],"traps":[{"en":"The gap needs the exact word you hear, with its ending: \"forests\", not \"forest\". Spelling and plural count.","tr":"Boşluğa duyduğun kelimenin aynısı, ekiyle birlikte gerekir: \"forest\" değil \"forests\". Yazım ve çoğul önemlidir.","fa":"جای خالی دقیقاً همان کلمه‌ای را که می‌شنوی، با پسوندش می‌خواهد: «forests»، نه «forest». املا و جمع مهم است."},{"en":"Expectation first, fact second: \"You might think most cork goes into floors, but in fact most of it becomes bottle stoppers.\"","tr":"Önce beklenti, sonra gerçek: \"Mantarın çoğunun zemine gittiğini düşünebilirsin, ama aslında çoğu şişe tıpası olur.\"","fa":"اول انتظار، بعد واقعیت: «شاید فکر کنی بیشترِ چوب‌پنبه صرف کف‌پوش می‌شود، اما در واقع بیشترش درِ بطری می‌شود»."},{"en":"Part 4 has no break. If you miss one answer, let it go and move to the next heading.","tr":"Part 4’te ara yoktur. Bir cevabı kaçırırsan bırak ve bir sonraki başlığa geç.","fa":"Part 4 مکث ندارد. اگر جوابی را از دست دادی، رهایش کن و برو سراغ عنوان بعدی."}],"example":{"text":"\"Let’s turn now to the problems. The first is the weather: long dry periods have cut harvests by a third.\"","item":"Problems: periods of ___ weather","answer":"dry","why":{"en":"\"Let’s turn now to\" moves you to the Problems heading; the gap needs an adjective before weather.","tr":"\"Let’s turn now to\" seni Problems başlığına geçirir; boşluk weather’dan önce bir sıfat istiyor.","fa":"«Let’s turn now to» تو را به عنوان Problems می‌برد؛ جای خالی یک صفت قبل از weather می‌خواهد."}}},{"id":"L4-nature","ctx":["L4-nature"],"title":{"en":"Animals, plants and ecosystems","tr":"Hayvanlar, bitkiler ve ekosistemler","fa":"حیوان‌ها، گیاهان و زیست‌بوم‌ها"},"asks":{"en":"A lecturer explains a species, a plant or an ecosystem: where it lives, what it eats, how it behaves, what threatens it and what researchers are doing. The notes follow those headings.","tr":"Bir öğretim görevlisi bir türü, bir bitkiyi ya da bir ekosistemi anlatır: nerede yaşadığı, ne yediği, nasıl davrandığı, onu neyin tehdit ettiği ve araştırmacıların ne yaptığı. Notlar bu başlıkları izler.","fa":"یک سخنران یک گونه، یک گیاه یا یک زیست‌بوم را توضیح می‌دهد: کجا زندگی می‌کند، چه می‌خورد، چه رفتاری دارد، چه چیزی تهدیدش می‌کند و پژوهشگرها چه می‌کنند. یادداشت‌ها همین عنوان‌ها را دنبال می‌کنند."},"fields":["Habitat","Diet","Behaviour","Threats","Research methods","Conservation","Uses to humans"],"words":[{"a":"habitat","b":"where it lives / its natural home","tr":"yaşam alanı","fa":"زیستگاه"},{"a":"predators","b":"animals that hunt it","tr":"avcı hayvanlar","fa":"شکارچی‌ها"},{"a":"prey","b":"the animals it hunts","tr":"av","fa":"طعمه"},{"a":"species","b":"a type of animal or plant","tr":"tür","fa":"گونه"},{"a":"breed","b":"produce young / have babies","tr":"üremek","fa":"تولیدمثل کردن"},{"a":"migrate","b":"travel long distances every year","tr":"göç etmek","fa":"مهاجرت کردن"},{"a":"decline","b":"fall in numbers","tr":"azalma","fa":"کاهش"},{"a":"threat","b":"a danger to its survival","tr":"tehdit","fa":"تهدید"},{"a":"native","b":"it has always lived here","tr":"yerli","fa":"بومی"},{"a":"invasive","b":"brought in from elsewhere and spreading","tr":"istilacı","fa":"مهاجم"},{"a":"soil","b":"the ground plants grow in","tr":"toprak","fa":"خاک"},{"a":"track","b":"follow where it goes with a small device","tr":"izlemek","fa":"ردیابی کردن"},{"a":"conservation","b":"protecting it","tr":"koruma","fa":"حفاظت"}],"traps":[{"en":"Plurals and spelling count: insects, seeds, leaves. Write the form you hear.","tr":"Çoğul ve yazım önemlidir: insects, seeds, leaves. Duyduğun biçimi yaz.","fa":"جمع و املا مهم است: insects، seeds، leaves. همان شکلی را که می‌شنوی بنویس."},{"en":"An old belief comes first: \"it was once thought to eat fish, but in fact it mainly eats...\". Write what comes after \"in fact\".","tr":"Önce eski bir inanış gelir: \"bir zamanlar balık yediği sanılıyordu ama aslında çoğunlukla ... yiyor\". \"In fact\"ten sonra geleni yaz.","fa":"اول یک باور قدیمی می‌آید: «زمانی فکر می‌کردند ماهی می‌خورد، ولی در واقع بیشتر ... می‌خورد». چیزی را بنویس که بعد از «in fact» می‌آید."}],"example":{"lines":[["Lecturer","For a long time, people believed these birds nested on cliffs."],["Lecturer","But recent tracking shows that most of them actually nest in old trees, well away from the coast."]],"item":"Nesting site: mainly old ___   (ONE WORD ONLY)","answer":"trees","why":{"en":"Cliffs are the old belief. \"Actually nest in old trees\": write trees, with the s.","tr":"Kayalıklar eski inanış. \"Actually nest in old trees\": trees yaz, s ile.","fa":"صخره‌ها باور قدیمی است. «Actually nest in old trees»: بنویس trees، با s."}},"general":true,"patterns":["L4-nature"],"often":{"pattern":"L4-nature","n":14,"of":40,"label":{"en":"Comes up often in the real exam: 14 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 14’ünde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۴ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"One talk, ten notes, no break","tr":"Bir konuşma, on not, ara yok","fa":"یک سخنرانی، ده یادداشت، بدون مکث"},"body":{"en":"Questions 31-40 are notes under five or six headings. Write ONE WORD ONLY. You read the notes for about 45 seconds, and then the lecture plays from start to finish without a pause.","tr":"Soru 31-40, beş altı başlık altındaki notlardır. Yalnızca BİR KELİME yaz. Notları yaklaşık 45 saniye okursun, sonra ders baştan sona hiç durmadan çalar.","fa":"سؤال‌های ۳۱ تا ۴۰ یادداشت‌هایی زیر پنج شش عنوان‌اند. فقط یک کلمه بنویس. حدود ۴۵ ثانیه یادداشت‌ها را می‌خوانی و بعد سخنرانی از اول تا آخر بدون مکث پخش می‌شود."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Four steps","tr":"Dört adım","fa":"چهار قدم"},"steps":[{"en":"Read the headings first: they are the map of the talk.","tr":"Önce başlıkları oku: konuşmanın haritası onlardır.","fa":"اول عنوان‌ها را بخوان: آن‌ها نقشه‌ی سخنرانی‌اند."},{"en":"For each gap, guess the kind of word: a noun, an adjective, singular or plural.","tr":"Her boşluk için kelime türünü tahmin et: isim mi, sıfat mı, tekil mi, çoğul mu.","fa":"برای هر جای خالی نوع کلمه را حدس بزن: اسم یا صفت، مفرد یا جمع."},{"en":"Listen for signposts to know where you are: first of all, let’s turn to, the second problem, this brings me to.","tr":"Nerede olduğunu bilmek için geçiş ifadelerini dinle: first of all, let’s turn to, the second problem, this brings me to.","fa":"برای اینکه بدانی کجایی، به نشانه‌ها گوش کن: first of all، let’s turn to، the second problem، this brings me to."},{"en":"Write the word you hear, with its ending, and check the spelling at the end.","tr":"Duyduğun kelimeyi ekiyle yaz, sonunda yazımı kontrol et.","fa":"کلمه‌ای را که می‌شنوی با پسوندش بنویس و آخر کار املایش را چک کن."}]},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Signposts tell you the next heading","tr":"Geçiş ifadeleri sonraki başlığı söyler","fa":"نشانه‌ها عنوان بعدی را خبر می‌دهند"},"table":{"headers":{"en":["You hear","Move to"],"tr":["Duyduğun","Geç"],"fa":["می‌شنوی","برو به"]},"rows":[["First of all...","the first heading"],["Let’s turn now to the problems.","Problems"],["The second problem is...","the next point under the same heading"],["This brings me to the last part...","the last heading"]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One note, step by step","tr":"Bir not, adım adım","fa":"یک یادداشت، قدم به قدم"},"instruction":"Complete the notes below. Write ONE WORD ONLY for each answer.","item":"Uses · mainly for making ___","text":"\"People often think of furniture, but in fact most of the wood from these forests ends up as paper.\"","answer":"paper","walk":[{"en":"The heading is Uses, and \"making ___\" needs a noun.","tr":"Başlık Uses ve \"making ___\" bir isim istiyor.","fa":"عنوان Uses است و «making ___» یک اسم می‌خواهد."},{"en":"Furniture is what \"people often think\": a distractor.","tr":"Mobilya \"insanların sık düşündüğü\" şey: çeldirici.","fa":"مبلمان چیزی است که «مردم اغلب فکر می‌کنند»: گزینه‌ی انحرافی."},{"en":"\"In fact most... ends up as paper\": write paper, one word.","tr":"\"Aslında çoğu... kâğıt oluyor\": paper yaz, tek kelime.","fa":"«در واقع بیشترش... کاغذ می‌شود»: paper را بنویس، یک کلمه."}]},"quick":{"prompt":"Notes: \"Seeds are spread by ___\" (ONE WORD ONLY). You hear: \"The seeds are mainly carried away by birds.\" What do you write?","options":["bird","birds","by birds"],"correct":1,"why":{"en":"Write the exact word with its plural s. \"by\" is printed already.","tr":"Kelimeyi çoğul s ekiyle aynen yaz. \"by\" zaten yazılı.","fa":"کلمه را دقیقاً با s جمع بنویس. «by» از قبل چاپ شده."}},"remember":{"en":"Follow the signposts, keep moving, and copy the word exactly as you hear it.","tr":"Geçiş ifadelerini takip et, ilerlemeye devam et ve kelimeyi tam duyduğun gibi yaz.","fa":"نشانه‌ها را دنبال کن، جلو برو و کلمه را دقیقاً همان‌طور که می‌شنوی بنویس."},"type":"explain","id":"c-x01-l4-e","course":"ielts-exams","exam":"exam-01","unit":"x01-l4"},"drill":{"type":"drill","skill":"listening","part":"Listening Part 4","title":{"en":"Natural rubber","tr":"Doğal kauçuk","fa":"لاستیک طبیعی"},"timed":8,"ctx":["L4-nature"],"script":[{"who":"Lecturer","line":"Good morning, everyone. Today I'm going to talk about a material that most of us use every day without thinking about it: rubber. I'll look at where it comes from, why its supply is less secure than you might expect, and what scientists are doing about it."},{"who":"Lecturer","line":"First of all, let's be clear that there are two kinds of rubber. Natural rubber comes from plants, and synthetic rubber is made in factories. Roughly half of all the rubber used in the world today is natural, and that half is the one I want to focus on first."},{"who":"Lecturer","line":"Almost all natural rubber comes from a single species, the rubber tree. It originally grew wild in the rainforests of South America, scattered among thousands of other trees. The material we want is a white liquid called latex. Workers collect it by cutting a thin line in the bark, early in the morning, and the latex runs slowly down into a small cup tied to the trunk. A good worker can tap several hundred trees in a day, and a tree can be tapped for about twenty-five years."},{"who":"Lecturer","line":"Now, you might expect most rubber to come from South America, but in fact very little does. In the late nineteenth century, seeds were taken to Asia and planted there, and today most natural rubber is produced in Southeast Asia. What's interesting is who produces it. It isn't mainly large companies. Around eighty-five per cent comes from family farmers, each working a few hectares of land."},{"who":"Lecturer","line":"So what is all this rubber used for? You might think of gloves or shoes, but those are small markets. About seventy per cent of natural rubber goes into tyres, especially for lorries and aircraft."},{"who":"Lecturer","line":"Let's turn now to the problems. The first is a genetic one. Because the plantations in Asia all grew from a small number of seeds, the trees are genetically very similar. In a wild forest, variety protects a species: some trees resist a disease even if others die. On a plantation where every tree is almost the same, one disease can affect them all."},{"who":"Lecturer","line":"And there is a disease that worries growers a great deal. It's caused by a fungus that attacks the leaves. It's the main reason why large plantations never succeeded in South America, and so far it hasn't reached Asia, thanks partly to strict checks on plants and soil arriving at ports and airports. But with modern travel, many scientists think it's only a matter of time."},{"who":"Lecturer","line":"The second problem is economic. The price of rubber goes up and down a lot, and for several years now it has been low. When prices are low, many farmers simply give up and replace their rubber trees with crops that earn more. This matters more than it first appears. Fewer trees today means less rubber in about seven years' time, because that's how long a young tree takes to produce latex."},{"who":"Lecturer","line":"The obvious question is: why not just use synthetic rubber? Synthetic rubber was developed on a large scale in the twentieth century, and it's made from oil. It's cheap and reliable, and for many products, from the soles of trainers to the seals in a washing machine, it works perfectly well. But it doesn't do everything. Natural rubber stays strong and flexible when it gets hot, and synthetic rubber doesn't handle heat as well. That's why the tyres of aircraft, which get extremely hot on landing, still need a large share of natural rubber."},{"who":"Lecturer","line":"This brings me to the last part of the talk: other plants that produce rubber. The most promising is a shrub called guayule, which grows in the dry regions of northern Mexico and the south-western United States. One big advantage is that it needs very little water, so it can be grown on land where rubber trees could never survive. Unlike the rubber tree, it isn't tapped. Instead, the whole plant is harvested and the rubber is taken from the stems."},{"who":"Lecturer","line":"Guayule rubber has another advantage. Some people react badly to products made from ordinary latex, such as medical gloves. Guayule latex doesn't seem to cause the same reaction, so it could be very useful for hospital staff and patients with allergies."},{"who":"Lecturer","line":"There are difficulties, of course. At the moment guayule rubber costs more to produce, and the processing plants are few and small. But a number of tyre companies are already testing it, and if it works, it could reduce our dependence on one species of tree. In other words, the future of a very ordinary material may depend on a rather unusual desert plant. Next week we'll look at another plant material, cork."}],"notes":{"title":"Natural rubber","headings":["The rubber tree","Production","Problems","Synthetic rubber","Guayule"],"extra":["Guayule · needs very little water and grows in dry regions","Guayule · the whole plant is harvested"]},"groups":[{"instruction":"Questions 31-40. Complete the notes below. Write ONE WORD ONLY for each answer.","qtype":"note","questions":[{"n":31,"kind":"gap","prompt":"The rubber tree · originally grew wild in the ___ of South America","accept":["rainforests"],"limit":1,"evidence":"grew wild in the rainforests of South America","why":{"en":"Write the plural you hear: rainforests.","tr":"Duyduğun çoğulu yaz: rainforests.","fa":"همان جمعی را که می‌شنوی بنویس: rainforests."},"trap":["TR-plural"]},{"n":32,"kind":"gap","prompt":"The rubber tree · latex is collected by cutting a thin line in the ___","accept":["bark"],"limit":1,"evidence":"cutting a thin line in the bark","why":{"en":"\"By cutting a thin line in the bark.\"","tr":"\"Kabukta ince bir çizgi açarak.\"","fa":"«با بریدن یک خط باریک روی پوست درخت»."},"trap":["TR-paraphrase"]},{"n":33,"kind":"gap","prompt":"Production · about 85% is produced by family ___ in Southeast Asia","accept":["farmers"],"limit":1,"evidence":"comes from family farmers","why":{"en":"\"It isn’t mainly large companies... family farmers.\" Companies are the distractor.","tr":"\"Çoğunlukla büyük şirketler değil... aile çiftçileri.\" Şirketler çeldirici.","fa":"«بیشترش شرکت‌های بزرگ نیستند... کشاورزهای خانوادگی». شرکت‌ها گزینه‌ی انحرافی‌اند."},"trap":["TR-paraphrase","TR-plural"]},{"n":34,"kind":"gap","prompt":"Production · about 70% is used to make ___","accept":["tyres"],"limit":1,"evidence":"About seventy per cent of natural rubber goes into tyres","why":{"en":"Gloves and shoes are \"small markets\"; seventy per cent \"goes into\" tyres = is used to make.","tr":"Eldiven ve ayakkabı \"küçük pazarlar\"; yüzde yetmişi lastiğe \"gider\" = lastik yapımında kullanılır.","fa":"دستکش و کفش «بازارهای کوچکی‌اند»؛ هفتاد درصد «صرف لاستیک می‌شود» یعنی برای ساختن لاستیک استفاده می‌شود."},"trap":["TR-paraphrase"]},{"n":35,"kind":"gap","prompt":"Problems · plantation trees are genetically very ___","accept":["similar"],"limit":1,"evidence":"the trees are genetically very similar","why":{"en":"\"The trees are genetically very similar\", because they grew from a few seeds.","tr":"\"Ağaçlar genetik olarak çok benzer\", çünkü az sayıda tohumdan çıktılar.","fa":"«درخت‌ها از نظر ژنتیکی خیلی شبیه‌اند»، چون از تعداد کمی دانه روییده‌اند."},"trap":["TR-paraphrase"]},{"n":36,"kind":"gap","prompt":"Problems · a disease caused by a ___ that attacks the leaves","accept":["fungus"],"limit":1,"evidence":"caused by a fungus that attacks the leaves","why":{"en":"\"It’s caused by a fungus that attacks the leaves.\" Spell it f-u-n-g-u-s.","tr":"\"Yaprakları saldıran bir mantar neden oluyor.\" Yazımı: f-u-n-g-u-s.","fa":"«عاملش قارچی است که به برگ‌ها حمله می‌کند». املایش f-u-n-g-u-s است."},"trap":["TR-paraphrase"]},{"n":37,"kind":"gap","prompt":"Problems · low ___ make farmers replace rubber trees with other crops","accept":["prices"],"limit":1,"evidence":"When prices are low","why":{"en":"\"When prices are low, many farmers simply give up.\" Plural: prices.","tr":"\"Fiyatlar düşükken birçok çiftçi bırakıyor.\" Çoğul: prices.","fa":"«وقتی قیمت‌ها پایین است، خیلی از کشاورزها دست می‌کشند». جمع: prices."},"trap":["TR-plural"]},{"n":38,"kind":"gap","prompt":"Synthetic rubber · made from ___","accept":["oil"],"limit":1,"evidence":"it's made from oil","why":{"en":"\"It’s made from oil.\"","tr":"\"Petrolden yapılır.\"","fa":"«از نفت ساخته می‌شود»."},"trap":["TR-paraphrase"]},{"n":39,"kind":"gap","prompt":"Synthetic rubber · not as good as natural rubber at dealing with ___","accept":["heat"],"limit":1,"evidence":"doesn't handle heat as well","why":{"en":"\"Synthetic rubber doesn’t handle heat as well\" = not as good at dealing with heat.","tr":"\"Sentetik kauçuk ısıyla o kadar iyi baş edemez.\"","fa":"«لاستیک مصنوعی گرما را به آن خوبی تحمل نمی‌کند»."},"trap":["TR-paraphrase"]},{"n":40,"kind":"gap","prompt":"Guayule · its latex could be used for patients with ___","accept":["allergies"],"limit":1,"evidence":"patients with allergies","why":{"en":"\"Hospital staff and patients with allergies\". Plural, as you hear it.","tr":"\"Hastane çalışanları ve alerjisi olan hastalar\". Duyduğun gibi çoğul.","fa":"«کارکنان بیمارستان و بیمارانی که آلرژی دارند». جمع، همان‌طور که می‌شنوی."},"trap":["TR-plural","TR-limit"]}]}],"audio":{"voices":{"Announcer":{"accent":"British (standard Southern)","gender":"M","tts":{"engine":"kokoro","voice":"bm_george"},"role":"Recorded rubric"},"Lecturer":{"accent":"British (standard Southern)","gender":"F","tts":{"engine":"kokoro","voice":"bf_isabella"},"role":"Lecturer"}},"sequence":[{"type":"announcer","text":"Part 4. You will hear a lecture about natural rubber. First, you have some time to look at Questions 31 to 40."},{"type":"pause","seconds":45,"note":"reading time, Questions 31-40"},{"type":"announcer","text":"Now listen carefully and answer Questions 31 to 40."},{"type":"sfx","note":"lecture-room acoustics: slight room reverb; 1.5 s pause between paragraphs"},{"type":"lines","from":0,"to":11},{"type":"announcer","text":"That is the end of Part 4. You now have two minutes to check your answers.","after":120}]},"id":"c-x01-l4-d","course":"ielts-exams","exam":"exam-01","unit":"x01-l4"},"exit":{"type":"exit","items":[{"tests":"paraphrase","point":3,"prompt":"Notes: \"Main use: ___\". Which phrase in a lecture leads you to it?","options":["about seventy per cent goes into","you might think of","this brings me to"],"correct":0,"why":{"en":"\"Seventy per cent goes into\" gives the main use; \"you might think of\" introduces a distractor.","tr":"\"Yüzde yetmişi ... gider\" ana kullanımı verir; \"you might think of\" çeldiriciyi getirir.","fa":"«هفتاد درصدش صرف ... می‌شود» کاربرد اصلی را می‌دهد؛ «you might think of» گزینه‌ی انحرافی را می‌آورد."}},{"tests":"word","point":1,"prompt":"A product that is \"synthetic\" is...","options":["grown on a plantation","collected from the wild","made in a factory, not taken from a plant or animal"],"correct":2,"why":{"en":"Synthetic = made by people in factories, here from oil.","tr":"Sentetik = insanların fabrikada yaptığı, burada petrolden.","fa":"synthetic یعنی ساخته‌ی دست انسان در کارخانه؛ این‌جا از نفت."}},{"tests":"method","point":3,"prompt":"You hear \"Let’s turn now to the problems.\" What does this tell you?","options":["The lecture is ending","Move to the Problems heading","Write the word \"problems\""],"correct":1,"why":{"en":"A signpost moves you to the next heading of the notes.","tr":"Geçiş ifadesi seni notların sonraki başlığına götürür.","fa":"نشانه تو را به عنوان بعدی یادداشت‌ها می‌برد."}},{"tests":"trap","point":2,"prompt":"Notes: \"found mainly in tropical ___\" (ONE WORD ONLY). You hear \"mainly in tropical forests\". What do you write?","options":["forests","forest","tropical forests"],"correct":0,"why":{"en":"Write the exact form you hear, with the plural s; \"tropical\" is printed.","tr":"Duyduğun biçimi çoğul s ile aynen yaz; \"tropical\" yazılı.","fa":"همان شکلی را که می‌شنوی با s جمع بنویس؛ «tropical» چاپ شده."}},{"tests":"method","point":1,"prompt":"You missed the answer to Question 34. The lecturer is now on the next heading. What do you do?","options":["Wait for the lecturer to repeat it","Stop and guess before you listen on","Leave it and follow the next note"],"correct":2,"why":{"en":"Part 4 has no break and nothing is repeated. Move on; guess Question 34 at the end.","tr":"Part 4’te ara yok, hiçbir şey tekrarlanmaz. Devam et; 34’ü sonda tahmin et.","fa":"Part 4 مکث ندارد و چیزی تکرار نمی‌شود. جلو برو؛ سؤال ۳۴ را آخر کار حدس بزن."}}],"id":"c-x01-l4-x","course":"ielts-exams","exam":"exam-01","unit":"x01-l4"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
